functions.generate_matrix:
int generate_matrix(float ***matrix, int x, int y, _Bool random)
{
    *matrix = malloc(sizeof(float *) * x);
    if (!random)
    {
        for (int i = 0; i < x; ++i)
        {
            (*matrix)[i] = malloc(sizeof(float) * x);
            for (int j = 0; j < y; ++j)
            {
                (*matrix)[i][j] = (float)(j + i * x);
            }
        }
    }
    else
    {
        for (int i = 0; i < x; ++i)
        {
            (*matrix)[i] = malloc(sizeof(float) * y);
            for (int j = 0; j < y; ++j)
            {
                (*matrix)[i][j] = (float)rand();
            }
        }
    }
    return 0;
}

functions.free_matrix:
int free_matrix(float ***matrix, int x)
{
    for (int i = 0; i < x; ++i)
    {
        free((*matrix)[i]);
    }
    free(*matrix);
    *matrix = ((void *)0);
    return 0;
}

functions.multiply:
int multiply(float **m1, float **m2, float **r, int x1, int y1, int x2, int y2, int method)
{
    if (y1 - x2)
    {
        printf(
            "The number of columns in the first matrix must be equal to the number of rows in the second matrix. \n");
        return -1;
    }
    switch (method)
    {
    case 1:
        algorithm1(m1, m2, r, x1, y1, x2, y2);
        break;
    case 2:
        algorithm2(m1, m2, r, x1);
        break;
    case 3:
        algorithm3(m1, m2, r, x1, y1, x2, y2);
        break;
    default:
        printf("Choose the correct method!\n");
        return -1;
    }
    return 0;
}

functions.algorithm1:
int algorithm1(float **m1, float **m2, float **r, int x1, int y1, int x2, int y2)
{
    for (int i = 0; i < x1; ++i)
    {
        for (int j = 0; j < y2; ++j)
        {
            r[i][j] = 0;
            for (int k = 0; k < y1; ++k)
            {
                r[i][j] += m1[i][k] * m2[k][j];
            }
        }
    }
    return 0;
}

functions.algorithm3:
int algorithm3(float **m1, float **m2, float **r, int x1, int y1, int x2, int y2)
{
    for (int i = 0; i < x1; ++i)
    {
        for (int j = 0; j < y2; ++j)
        {
            r[i][j] = 0;
        }
    }
    for (int i = 0; i < x1; ++i)
    {
        for (int k = 0; k < y1; ++k)
        {
            for (int j = 0; j < y2; ++j)
            {
                r[i][j] += m1[i][k] * m2[k][j];
            }
        }
    }
    return 0;
}

